import { PieChartComponent } from '@/components/charts/PieChart';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { useEffect, useState } from 'react';
import { ChartConfig } from '@/components/ui/chart';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import List from '@/features/car/components/statistics/List';
import { AttendanceDashboardChart } from '../../types/attendanceStats.types';

type Props = {
    /** Required by API: GET /attendance-employee-stats?employee_id=… (see NEW_ENDPOINTS.md). */
    employeeId?: string;
};

export default function AttendanceStats({ employeeId }: Props) {
    const [stats, setStats] = useState<AttendanceDashboardChart | null>(null);
    const [selectedValue, setSelectedValue] = useState('');

    useEffect(() => {
        if (!employeeId) {
            setStats(null);
            return;
        }
        const fetchStats = async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.employeeAttendance.analysis,
                    queryParams: {
                        employee_id: employeeId,
                        // Optional date range can be wired to period selector later:
                        // ...(selectedValue && { period: selectedValue }),
                    },
                });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, [selectedValue, employeeId]);

    let chartData: { days: string; visitors: number; fill: string }[] = [];
    let data: string[] = ['حضور', 'غياب', 'إجازة', 'تأخير'];

    if (stats) {
        const entries: [string, number][] = [
            ['present', stats.present],
            ['absent', stats.absent],
            ['leave', stats.leave],
            ['late', stats.late],
        ];
        chartData = entries.map(([key, value]) => ({
            days: key,
            visitors: value,
            fill: `var(--color-${key})`,
        }));

        data = [
            `${stats.present} حضور`,
            `${stats.absent} غياب`,
            `${stats.leave} إجازة`,
            `${stats.late} تأخير`,
        ];
    }

    const chartConfig = {
        visitors: {
            label: 'Visitors',
        },
        present: {
            label: 'حضور',
            color: 'hsl(var(--chart-1))',
        },
        absent: {
            label: 'غياب',
            color: 'hsl(var(--chart-5))',
        },
        leave: {
            label: 'إجازة',
            color: 'hsl(var(--chart-4))',
        },
        late: {
            label: 'تأخير',
            color: 'hsl(var(--chart-3))',
        },
    } satisfies ChartConfig;

    return (
        <div className="flex flex-col justify-between p-4 shadow-[0px_2px_12px_0px_#14142B14] rounded-[0.5rem]">
            <div className="flex flex-row justify-between mb-4">
                <UnderlineHeading text="الحضور" />
                <CustomSelect
                    options={[
                        { label: 'يومي', value: 'يومي' },
                        { label: 'أسبوعي ', value: 'أسبوعي ' },
                        { label: 'شهري', value: 'شهري' },
                        { label: 'سنوي', value: 'سنوي' },
                    ]}
                    value={selectedValue}
                    onValueChange={setSelectedValue}
                    placeholder="القائمة"
                    width="min-w-[101px]"
                />
            </div>
            <div className="flex flex-row items-center justify-between mb-8">
                {!employeeId ? (
                    <p className="text-sm text-[#625E74] text-end w-full">
                        اختر صفحة موظف لعرض إحصائيات الحضور، أو استخدم صفحة تفاصيل الموظف.
                    </p>
                ) : (
                    <>
                        <List text={data} />
                        <PieChartComponent chartData={chartData} chartConfig={chartConfig} />
                    </>
                )}
            </div>
        </div>
    );
}
